pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with smooth non-linear shaping.
    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Coupling with stream progress: later in the stream, dead space hurts more.
    score += 12.0 * progress * norm_pr * norm_pr;

    // Reward tight fits (small post_residual relative to capacity).
    score -= 8.0 * (1.0 - norm_pr).powi(3) * (1.0 - progress);

    // Penalize creating residual that cannot fit the next item (smooth interaction).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - pr).max(0.0) / cap;
        score += 10.0 * gap * gap * (1.0 + progress);
        // Reward residual that exactly accommodates the next item.
        score -= 4.0 * (-((pr - nxt) / cap).powi(2) * 20.0).exp();
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Many open bins: prefer filling existing ones rather than spreading.
    score += 0.4 * open_bins_count as f64 * norm_pr;

    // Mean residual coupling: penalize bins far from the mean residual (fragmentation).
    score += 3.0 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: neutral-ish baseline so it only wins when fits are terrible.
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes (dead space) are penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Class 1: tiny dead space (pr <= 10) is excellent -> strong reward.
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 10 {
        score -= 25.0;
    } else {
        // Modulo-10 class of the residual: multiples of 10 are "harmonic"
        // with typical item sizes and more likely reusable.
        let harmonic = (pr % 10) == 0;
        if harmonic {
            score -= 8.0;
        } else {
            score += (pr % 10) as f64 * 0.7; // non-harmonic residue penalty
        }
        // Integer-division threshold: large leftover (> half capacity) is
        // flexible space; medium leftover (10..50) is awkward.
        if pr > bin_capacity / 2 {
            score -= 5.0;
        } else if pr <= bin_capacity / 4 {
            score += 4.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (chain fit).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            if slack <= 10.0 {
                score -= 12.0;
            } else {
                score += slack * 0.15;
            }
        } else {
            // Next item cannot follow here: mild penalty scaled by gap.
            score += (next_item_size - pr) as f64 * 0.1;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Stream progression: late in the stream, prefer tighter packing
    // (avoid sprawling into many bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 6.0 * (1.0 - prf / cap);

    // Prefer bins already below mean residual (consolidating loose space).
    score += (prf - mean_residual) * 0.05;

    // Many open bins: encourage closing them out by using tight fits.
    if open_bins_count > 4 {
        score -= 3.0 * (1.0 - prf / cap);
    }

    // New-bin candidate: only attractive when no good fit exists
    // (handled by comparisons, but give it a neutral-ish base with a
    // slight penalty so it wins only against bad fits).
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard penalty for unusable dead space: gaps that no plausible item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize gaps that can only be filled by the smallest items.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward perfect fills strongly.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward leaving a gap exactly matching the next item (lookahead synergy).
    if next_item_size > 0 {
        let gap = post_residual as f64;
        let nxt = next_item_size as f64;
        if gap >= nxt {
            let d = gap - nxt;
            if d == 0.0 { score -= 40.0; }
            else if d < 10.0 { score += 30.0; }
        }
    }

    // Last-chance pressure: if this is the only bin that fits, prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when existing residuals are badly fragmented
    // or the item is huge and fits nothing well.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - mean_residual.fract()).max(0.0);
        let pressure = (open_bins_count as f64).ln().max(0.0);
        let big_item = if item_size > 70 { 25.0 } else { 0.0 };
        let poor_alternatives = if fitting_bins_count == 0 { 50.0 } else { 0.0 };
        score = bin_capacity as f64 - 15.0 + pressure - big_item - poor_alternatives
            + if mean_residual < 25.0 { 30.0 } else { 0.0 };
    }

    // Mild pressure to consolidate into fewer bins as the stream progresses.
    score += (open_bins_count as f64) * 0.6 + (step_index as f64 / total_items.max(1) as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match within a small tolerance.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if diff <= 5.0 {
            score -= 25.0 - diff * 3.0;
        }
        // Dead space: post_residual too small for the lookahead item (unusable gap).
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }
    // Last usable bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }
    // If many bins fit, prefer tighter fits (post_residual already encodes this,
    // but add pressure relative to mean residual).
    if (post_residual as f64) > mean_residual * 1.3 {
        score += 6.0;
    } else if (post_residual as f64) < mean_residual * 0.7 {
        score -= 4.0;
    }
    // Late in the stream, tighten up: waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.5 * progress;

    // Discourage opening a new bin when a reasonably good fit exists in open bins.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if the new bin enables a perfect two-item pairing, allow it.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity
            && (bin_capacity - item_size - next_item_size) < 8 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but penalize leaving
    // awkward slivers (residual too small to be useful for typical items).
    let sliver = post_residual as f64;
    if sliver > 0.0 && sliver < 10.0 {
        score += 6.0; // dead space penalty
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Fit ratio: how much of the bin the item consumes.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fill_ratio;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Slight penalty for consuming a bin when alternatives exist,
        // scaled by how many other options exist.
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // this bin stays productive; reward it. If next item won't fit the
    // post-residual but would fit this bin only marginally, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0;
            // Chain bonus: near-exact chaining.
            let chain_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
            score -= 4.0 * (1.0 - chain_gap / 50.0).max(0.0);
        } else if next_item_size > bin_residual {
            // Next item needs a fresh bin anyway; this bin's residual is
            // free to waste, mildly reward using it now.
            score -= 3.0;
        } else {
            // Next item could have fit here if we placed better.
            score += 4.0;
        }
    }

    // Global state coupling: prefer filling bins with large residuals
    // when mean residual is high (consolidation pressure).
    let mean_gap = bin_residual as f64 - mean_residual;
    score -= 0.15 * mean_gap;

    // Time horizon: early in the stream, be more liberal about opening
    // new bins (spread items); late in the stream, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * (1.0 - progress);

    // New-bin candidate logic: an empty bin gets a baseline cost that
    // shrinks as the stream progresses and as open-bin count grows.
    if bin_residual == bin_capacity {
        // Opening a new bin is cheap early, expensive late.
        score += 18.0 * progress;
        // If current bin would leave a big unusable residual, new bin wins.
        if post_residual > 0 && post_residual < 15 {
            score -= 10.0;
        }
        // If only one fitting bin exists and it's tight, opening new bin
        // is reasonable; slight discount.
        if fitting_bins_count <= 2 {
            score -= 5.0;
        }
        // Discourage hoarding too many open bins early.
        score += 0.5 * open_bins_count as f64;
    }

    // Mild preference for bins whose residual is a "round" multiple
    // (empirically common item sizes cluster near 10-20).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    // Small stabilizing term: bins with residual close to capacity minus
    // common item sizes are attractive targets.
    let target = (bin_capacity as i64 - item_size as i64) as f64;
    score -= 3.0 * (1.0 - ((bin_residual as f64 - target).abs() / 40.0)).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (1.0 - pr_norm);
    score -= poly * cap * (0.5 + progress);

    // Penalize large wasted residual as stream advances (dead space becomes costly)
    score += pr_norm * pr_norm * cap * progress * 0.8;

    // Reward tight fits: quadratic bonus shrinking with post_residual
    score -= (cap - pr) / cap * (cap - pr) * 0.05;

    // Last-chance bonus when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Lookahead: penalize residual that cannot hold the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr) * (0.3 + 0.5 * progress);
        } else {
            score -= 2.0 * (1.0 - pr / cap);
        }
    }

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).ln() * 1.5;

    // Deviation from mean residual: prefer bins near the mean to keep balance
    let dev = (pr - mean_residual).abs();
    score += dev * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: small residues (hard to reuse) are penalized
    // only mildly if they came from a tight fit; large residues are discounted by class.
    let residue_class = post_residual / 10; // integer-division harmonic bucket 0..=9
    score -= match residue_class {
        0 => 40.0,                    // near-perfect fit, almost no waste
        1 => 25.0,                    // excellent fit
        2 => 15.0,                    // good fit
        3 => 8.0,                     // decent
        4 => 3.0,                     // neutral
        5 => 0.0,                     // half-full remainder, still flexible
        6 => -2.0,                    // flexible zone
        7 => -4.0,
        8 => -5.0,
        _ => -6.0,                    // large residual, many future pairings possible
    };

    // Coupling with lookahead: reward when next item exactly or nearly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 35.0;
            } else if gap <= 15 {
                score -= 15.0;
            } else {
                score -= (gap as f64).sqrt() * 2.0;
            }
        } else {
            // next item cannot use this bin's residual: penalize by overshoot class
            let over = next_item_size - post_residual;
            score += (over / 10) as f64 * 6.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive for tight fits (small post_residual)
        // or when no open bin fits at all is signaled by fitting_bins_count == 0.
        let tightness = post_residual as f64 / bin_capacity as f64;
        score = 55.0 + tightness * 60.0;
        if post_residual <= 20 {
            score -= 45.0; // large item nearly fills a fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // forced: no open bin can take the item
        }
        // Early in stream, prefer consolidating into open bins slightly more.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 8.0;
    }

    // Mild pressure toward bins below mean residual (balancing dead space).
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals too small to hold any item
    // (items are >= 1, but small gaps < 10 are near-useless) are penalized hard.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0 + (10 - post_residual) as f64 * 50.0;
    }
    // Gaps that can only hold tiny items are also discouraged.
    else if post_residual >= 10 && post_residual < 20 {
        score += 50.0;
    }

    // Reward bins whose residual tightly matches the item (good fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 30.0;

    // Open-bins pressure: with many open bins, prefer filling existing ones;
    // with few open bins, mild tolerance for spreading.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 20.0;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well
    // (large residual waste would otherwise be created).
    if bin_residual == bin_capacity {
        let waste_if_placed = bin_capacity - item_size;
        if waste_if_placed > 60 {
            score -= 200.0; // big item in fresh bin is fine
        } else {
            score += 80.0 + pressure * 30.0; // discourage wasting a fresh bin
        }
    }

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Late in the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 40.0;
    }

    // Slight nudge toward bins below mean residual (balancing residuals).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 120.0 * (-diff / 25.0).exp();      // strong reward for perfect chain fit
        if post_residual == next_item_size {
            score -= 60.0;                          // exact 2-step match bonus
        }
        // Penalize residuals that can fit next item but leave >25 waste after
        if post_residual >= next_item_size && post_residual - next_item_size > 25 {
            score += 15.0;
        }
    }

    // Penalize dead space relative to mean residual across open bins.
    if post_residual as f64 > mean_residual {
        score += 0.4 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is large
    // and lookahead justifies fresh space.
    if bin_residual == bin_capacity {
        score += 45.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 70.0;  // fresh bin can serve both current and next item well
        }
        if item_size >= 60 {
            score -= 25.0;  // big items tolerate fresh bins
        }
    }

    // Tight fits are good: small post_residual is desirable, extra penalty for huge slack.
    if post_residual > 50 {
        score += 0.5 * (post_residual - 50) as f64;
    }

    // Late in stream, consolidate: favor bins with low post_residual even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (100.0 - post_residual as f64) / 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual < 10 {
        score += 30.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: bonus if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let leftover_after_next = post_residual - next_item_size;
            score -= 8.0 * (1.0 - leftover_after_next as f64 / bin_capacity as f64);
            if leftover_after_next < 10 {
                score += 6.0; // perfect two-item packing
            }
        } else {
            score += 4.0; // next item won't fit here; slight penalty
        }
    }

    // Global state: when mean residual is high, prefer fuller bins; when low,
    // spread items to keep residual flexibility.
    let mean_gap = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 10.0 * mean_gap;

    // Time horizon: early in stream, favor opening/keeping flexible bins;
    // late in stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * tightness;
    score += 8.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: discourage spreading, encourage filling existing ones.
    if open_bins_count > 3 {
        score -= 0.5 * open_bins_count as f64 * tightness;
    }

    // Brand-new empty bin candidate: only attractive when item is large
    // or current bins would leave bad dead space.
    if bin_residual == bin_capacity {
        score += 18.0;
        if item_size > 60 || post_residual == 0 {
            score -= 30.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr;
    score += 30.0 * (1.0 - progress) * x * (1.0 - x);
    score -= 25.0 * progress * (1.0 - x) * (1.0 - x);

    // Penalize dead space relative to mean residual smoothly
    let mr = mean_residual / cap;
    score += 15.0 * (x - mr) * (x - mr);

    // Last-chance bonus (smooth via fitting count)
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - x);
    }

    // Lookahead: reward residual that can still fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        score -= 10.0 * (1.0 - ((x - nx).abs() * 2.0).min(1.0)) * (1.0 - progress);
        score += 8.0 * (x - nx).abs() * progress;
    }

    // Slight pressure to consolidate when many bins are open
    score += 0.5 * open_bins_count as f64 * (1.0 - x);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by its class modulo capacity fractions.
    // Class A: post_residual in [0,10)  -> near-perfect fit, heavily reward.
    // Class B: post_residual in [10,20) -> still usable by smallest items.
    // Class C: larger leftovers -> penalize dead space quadratically.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;

    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else if post_residual < 10 {
        score -= 45.0;
    } else if post_residual < 20 {
        score -= 20.0;
    } else if post_residual < 34 {
        score -= 6.0;
    } else {
        // dead space beyond small-item reach: quadratic penalty scaled by progress
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 0.05 * pr * pr * (0.5 + 0.5 * progress);
    }

    // Modulo arithmetic on post_residual relative to capacity quarters:
    // leftover that is a multiple of small harmonic units is more reusable.
    let unit = post_residual % 10;
    if unit == 0 {
        score -= 8.0;
    } else if unit <= 3 {
        score -= 3.0;
    } else {
        score += unit as f64 * 0.5;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / c);
        } else {
            // next item won't fit here; slight penalty for stranding residual
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer tighter bins: reward closeness of item to bin_residual (best-fit flavor).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio;

    // New-bin candidate (empty bin): make it moderately attractive only when
    // mean residual across open bins is low or the item is large.
    if bin_residual == bin_capacity {
        let pressure = 1.0 - (mean_residual / c);
        score += 25.0 - 20.0 * pressure - 0.15 * item_size as f64;
        // discourage hoarding many open bins early
        score += open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Gaps below half the smallest item (<= 50) can still fit mid items; below 10 nothing fits.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 200.0; // total dead space
        } else if post_residual < 25 {
            score += 80.0;  // only fits tiny items
        } else if post_residual < 50 {
            score += 25.0;  // limited fit
        }
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Open-bin pressure: discourage scattering across many bins when residuals are plentiful.
    if open_bins_count > 1 {
        let pressure = (open_bins_count as f64).ln();
        // If mean residual is large, prefer filling existing bins (penalize new bins implicitly
        // via this additive term applied uniformly, but existing bins gain a discount).
        if bin_residual < bin_capacity {
            score -= 10.0 * pressure * (mean_residual / bin_capacity as f64);
        } else {
            score += 15.0 * pressure * (mean_residual / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual too small for the next item: penalize if it becomes dead space.
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the NEXT item exactly fills this bin's post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: this bin will be exactly closed by next item
        } else if next_item_size <= post_residual {
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack_after_next / bin_capacity as f64); // next item fits well here
        } else {
            // next item cannot use this bin's leftover: dead-space penalty scaled by gap
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 * (gap / 100.0).min(1.0);
        }
    }

    // Penalize large unusable leftovers relative to mean residual across open bins.
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Reward tight fits (small post residual relative to capacity).
    score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Mild preference to keep bin count low early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: neutral-ish baseline, slightly discouraged unless leftovers elsewhere are bad.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.3 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: squared post-residual penalizes dead space super-linearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer filling the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item won't fit here; slight penalty for wasting capacity
            // that could have held a larger future item.
            score += (next_item_size as f64 - post_residual as f64) * 0.05;
        }
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalty grows with number of open bins and early stream stage.
        score += 15.0 + open_bins_count as f64 * 2.0 + (1.0 - progress) * 10.0;
        // If only this new bin can fit the item, remove penalty.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer bins with residual below mean residual (consolidate small leftovers).
    if bin_residual != bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += diff * 0.3;
    }

    // Late stream: be greedier with tight fits, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let fit_norm = post / cap;

    // Base: quadratic penalty on post residual (dead space), slightly convex.
    let mut score = post * (1.0 + 0.8 * fit_norm * fit_norm);

    // Smooth non-linear coupling of dead space with stream progress:
    // early on, tight packing matters less; late, penalize residual harder.
    score *= 1.0 + 0.6 * progress * fit_norm;

    // Reward filling a bin nearly exactly, scaled by progress (smooth, no piecewise).
    let fill = 1.0 - fit_norm;
    score -= 12.0 * fill * fill * fill * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits in post_residual, reward this placement smoothly.
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 8.0 * (1.0 - slack) * (1.0 - slack);
    } else if next_item_size > 0 {
        // Next item won't fit: mild penalty proportional to leftover, growing with progress.
        score += 4.0 * fit_norm * (0.5 + progress);
    }

    // New-bin candidate handling: residual == capacity means empty bin.
    // Give it a baseline score that beats terrible fits but loses to decent ones.
    if bin_residual == bin_capacity {
        score = cap * (1.0 + 0.35 * progress)
            - 6.0 * (1.0 - (item_size as f64 / cap))
            + 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Mild penalty for spreading across many bins when mean residual is high.
    score += 0.05 * (mean_residual - post).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelmingly favored.
    if post_residual == 0 {
        score -= bin_capacity as f64 * 2.0;
    }

    // Harmonic classes of post_residual modulo small integers:
    // residuals divisible by 10/20/25/50 remain "usable" for typical item sizes.
    let r = post_residual;
    if r > 0 {
        if r % 10 == 0 { score -= 6.0; }
        if r % 20 == 0 { score -= 4.0; }
        if r % 25 == 0 { score -= 5.0; }
        if r % 50 == 0 { score -= 8.0; }
        if r % 100 == 0 { score -= 10.0; }
    }

    // Dead-space penalty: tiny nonzero residual is nearly useless.
    if r > 0 && r < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual,
    // penalize if next item fits but leaves another awkward remainder.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= bin_capacity as f64 * 1.5;
        } else if next_item_size < r {
            let next_post = r - next_item_size;
            if next_post % 10 == 0 {
                score -= 10.0;
            } else if next_post < 10 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make empty bins mildly unattractive so they are
    // chosen only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.1 * open_bins_count as f64;
    }

    // Late in the stream, tighten packing (less tolerance for slack).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * progress * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    // Medium gaps (10..20) are moderately wasteful.
    if post_residual >= 10 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 3.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward using the bin when it is the last chance before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing bins
    // over opening new ones; with few bins, consolidation is less critical.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual != bin_capacity {
        score -= 5.0 + 4.0 * pressure;
    } else {
        // New-bin candidate: penalize unless it offers a genuinely better fit.
        score += 15.0 + 6.0 * pressure;
        // Opening a new bin is acceptable if the item is large relative to
        // mean residual (existing bins are too full for good packing).
        let large_item = (item_size as f64) > mean_residual * 0.8;
        if large_item {
            score -= 20.0;
        }
    }

    // Lookahead: if next item would fit the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item barely misses, slight penalty for stranding space.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual && next_item_size - post_residual <= 5 {
        score += 8.0;
    }

    // Late in the stream, tighten up: avoid leaving scattered residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits: minimize post_residual aggressively.
    score *= 1.0;

    // --- 2-step lookahead: does the next item fit into the leftover space? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect chaining: next item exactly fills the remainder -> big reward.
            let gap = (post_residual - next_item_size) as f64;
            if gap == 0.0 {
                score -= 60.0; // exact two-item completion of the bin
            } else {
                // Reward proportional to how well the next item matches the gap.
                score -= 40.0 * (1.0 - gap / bin_capacity as f64);
            }
        } else {
            // Next item cannot use the leftover -> dead space penalty, scaled by waste.
            let dead = post_residual as f64;
            score += 0.5 * dead;
            // Extra penalty if the dead space is small-but-unusable (worst kind of waste).
            if dead < next_item_size as f64 && dead > 0.0 {
                score += 10.0;
            }
        }
    }

    // --- Relative-to-mean coupling: prefer bins whose residual deviates favorably ---
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        // Tighter-than-average bin: placing here consolidates fragmentation.
        score -= 8.0;
    } else {
        // Looser-than-average bin: mildly discourage, keep big reservoirs flexible.
        score += 4.0 * ((residual_f - mean_residual) / bin_capacity as f64);
    }

    // --- Last-chance bonus: if this is the only bin that fits, avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Only open a new bin if the item is large relative to capacity
        // and no good chaining is possible elsewhere; penalize mildly by default.
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        if large_item {
            score -= 15.0; // big items deserve fresh bins
        } else {
            score += 20.0; // prefer squeezing into open bins otherwise
        }
    }

    // --- Slight stream-progress adaptation: later in the stream, be greedier about tight fits ---
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness;

    // Penalize large dead space quadratically when post_residual is small but useless
    // (cannot fit typical next items).
    if post_residual > 0 {
        let waste = (post_residual as f64 / 100.0).powf(1.7);
        score += 6.0 * waste;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 12.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement chains nicely.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 9.0;
        } else if post_residual >= next_item_size {
            let chain_leftover = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - chain_leftover / bin_capacity as f64);
        } else {
            // Next item cannot fit here; mild penalty proportional to mismatch.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.05 * gap;
        }
    }

    // New-bin candidate logic: an empty bin has large residual; make it less attractive
    // unless existing bins are very fragmented or the item is large.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - bin_capacity as f64).abs();
        // Base penalty for opening a new bin, reduced when many bins are open and
        // fragmented, or late in the stream.
        let mut new_bin_penalty = 14.0;
        new_bin_penalty -= 0.4 * open_bins_count as f64;
        new_bin_penalty -= 6.0 * progress;
        new_bin_penalty -= 0.08 * fragmentation;
        score += new_bin_penalty.max(0.0);
    } else {
        // Existing bin: reward being close to mean residual (balanced usage),
        // penalize deviating bins to keep residuals homogeneous.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.06 * dev;
    }

    // Time horizon: early in the stream, be conservative with bins (prefer filling
    // existing ones); late in the stream, allow more freedom.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * tightness;

    // Prefer bins whose residual is barely above item size (best-fit flavor).
    let slack = (bin_residual - item_size) as f64;
    score += 0.04 * slack;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let smooth = progress * progress * (3.0 - 2.0 * progress); // smoothstep in [0,1]

    // Penalize large dead space increasingly as stream progresses (polynomial in pr_norm).
    score += 12.0 * smooth * pr_norm * pr_norm * (1.0 - pr_norm * 0.5);

    // Reward tight fits: low post residual gets a bonus, stronger late in stream.
    score -= 8.0 * (1.0 - smooth) * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Last-chance bin: strong reward to use it, modulated smoothly by progress.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * smooth;
    }

    // Lookahead: reward if next item fits the post-residual (smooth interaction).
    if next_item_size > 0 {
        let fits_next = if (post_residual as u64) >= (next_item_size as u64) { 1.0 } else { 0.0 };
        let gap = ((post_residual as f64) - (next_item_size as f64)).abs();
        score -= 6.0 * fits_next * (1.0 - gap / bin_capacity as f64);
    }

    // Slight penalty for spreading across many open bins when mean residual is high.
    score += 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64).powi(2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: post_residual divisible by small integers is "usable" dead space
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -40.0
    } else if pr % 10 == 0 {
        -8.0
    } else if pr % 5 == 0 {
        -4.0
    } else if pr % 2 == 0 {
        -1.5
    } else {
        1.0
    };
    score += class_bonus;

    // Integer division thresholds: small post_residual classes
    let q = pr / 10; // decade class
    if q <= 1 {
        score += 6.0; // tiny unusable remainder
    } else if q <= 3 {
        score += 2.0;
    }

    // Lookahead: does next item fit exactly or well into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0; // perfect follow-up fit
        } else if next_item_size <= pr {
            score -= 6.0;
        } else {
            score += 3.0; // next item cannot use this residual
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fits are bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 + 20.0 - 10.0 * progress
            + if next_item_size > 0 && next_item_size <= bin_capacity / 2 { -8.0 } else { 0.0 };
    }

    // Tight fits are good: reward small post_residual relative to item
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    // Crowding: many open bins -> prefer filling existing ones
    score += open_bins_count as f64 * 0.3;

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
