        score -= 25.0;
    } else {
        // Harmonic residuals (multiples of 10) are reusable by typical items.
        if pr % 10 == 0 {
            score -= 8.0;
        } else {
            score += (pr % 10) as f64 * 0.7;
        }
        // Large leftover is flexible; quarter-capacity leftover is awkward.
        if prf > cap / 2.0 {
            score -= 5.0;
        } else if prf <= cap / 4.0 {
            score += 4.0;
        }
    }

    // Lookahead: chain-fit with the next item.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            if slack <= 10.0 {
                score -= 12.0;
            } else {
                score += slack * 0.15;
            }
        } else {
            score += (next_item_size - pr) as f64 * 0.1;
        }
    }

    // Last-chance bin: avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Stream progression: late stream, prefer filling bins tighter.
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    score -= progress * 6.0 * (1.0 - prf / cap);

    // Consolidate loose space toward the mean residual.
    score += (prf - mean_residual) * 0.05;

    // Open-bin pressure: close out bins when many are open.
    if open_bins_count > 4 {
        score -= 3.0 * (1.0 - prf / cap);
    }

    // New-bin candidate: penalize so it only wins against genuinely bad fits.
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin anyway
        } else {
            // Opening a new bin is acceptable when the item is large relative
            // to mean residual (existing bins are too full for good packing).
            if (item_size as f64) > mean_residual * 0.8 {
                score -= 25.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

